        if pre1 is None and pre2 is None:
            return 0
        # If one is None and the other isn't, the one without pre-release is greater
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Both have pre-release, compare identifier by identifier
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            # Check if identifiers are all digits
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both are numeric, compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 != num2:
                    return -1 if num1 < num2 else 1
            elif is_digit1:
                # Only id1 is numeric, numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Only id2 is numeric, numeric sorts before non-numeric
                return 1
            else:
                # Both are non-numeric, compare lexically
                if id1 != id2:
                    return -1 if id1 < id2 else 1

        # All shared identifiers are equal, fewer identifiers sorts first
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1

        return 0

    def sort_key(version):
        parsed = parse_version(version)
        major, minor, patch, prerelease = parsed
        # Return tuple for sorting: (major, minor, patch, prerelease_sort_key)
        # For prerelease, we need a key that sorts None after any prerelease
        if prerelease is None:
            prerelease_key = (1,)  # Sorts after (0, ...)
